 *   Northgate user who entered it.
 */

/** One entry in a Northgate item. Discriminated by `type`. */
export type ChartEvent =
  | Visit
  | VitalSet
  | MedEvent
  | ProblemEvent
  | AllergyEvent
  | BillingDx
  | ListReviewed
  | ImportedResult
  | ReferralEvent
  | ReferralDx
  | ChartCorrection;

